// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testRegression_property() public {
        address payable malicious = payable(address(new MaliciousReceiver()));

        vm.deal(address(this), 1 ether);

        vm.deal(malicious, 1 wei);
        vm.prank(malicious);
        c.deposit{value: 1 wei}();

        vm.prank(malicious);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        assertTrue(!success, "Expected withdrawAll to revert");
    }
}

contract MaliciousReceiver {
    receive() external payable {
        revert("I refuse to receive");
    }
}
